INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1127868-cie204', 'stk-ra77al', 'CIE 204', 'info', '{"desc": "الكورس يعتمد بشكل كبير على الدكتور اللي منزل المادة ،، لأنها مادة تحتاج فهم\n\nالدكتور اللي منزلها السمستر الجاي لاهوري شداد … كيف الدكتور هذا مع المادة هذي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-204-digital-systems-design/120893/6", "user": "RA77AL", "ts": 1354383591000, "tid": 120893, "pn": 6}}', 1354383591000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1254169-cie204', 'stk-blood_prince', 'CIE 204', 'info', '{"desc": "CISE 204 Digital Systems Design\nPrerequisite: PHYS 102\nالكتاب: Digital Design\nالؤلف: M. Morris Mano & Michael D. Ciletti\n\nالمادة هذي موجودة عندنا وموجودة في قسم الإلكتريك باسم EE200 وموجودة عند قسم السي او اي باسم COE 202\nطبعا قسمنا فاتح مجال لو انك ما تبي تاخذها عندنا … تقدر تاخذها عند قسم الإلكتريك EE200\n\nطبيعة المادة هي الإنتقال من فهم البشر إلى فهم الحاسب الآلي … يعني بالبداية كيف تحول الأرقام والعمليات الحسابية من فهم البشر … إلى طريقة يفهمها الحاسب الآلي (From Analog To Digital ) ويجري على هذا المنوال تحويل الأرقام بأشكالها المختلفة (Decimal, Binary …etc)\nبعد كدا راح تتعلم كيف تعمل العمليات الحسابية (… Addition, Subtraction) باستخدام هذه الأشكال من الأرقام\n\nوأتوقع الكل يعرف إن الحاسب يفهم بطريقة (1,0) لهذا لازم تستعين بالعمليات المنطقية (AND, OR)\n\nبعدها راح تتعلم كيف تعمل العمليات المنطقية (Logic Functions) مثالها (AND, OR XOR) وكل عملية راح يكون لها شكل خاص بحيث تعرفها من شكلها وكنا نسميهم (Logic Gates)\n\nوبعدها راح يركز المنهج على طريقة تحويل كافة العمليات الحسابية … إلى طريقة إلكترونية (Hardware Circuits) باستخدام (Logic gates)\nفي البداية راح تبدأ بالعمليات البسيطة كالطرح والجمع … وبعده راح تبدأ الأمور بالتعقيد\n\nطبعا كل عملية تدرسها بالبداية وبعدها خلاص تستعملها كقطعة (Block) بحيث تحط السامبل حقها وخلاص … وتكمل على الشيء الجديد\n\nفي نهاية المادة هذي راح تكون عندك القدرة على تصميم دوائر كهربائية مختلفة لإجراء عمليات حسابية مختلفة مثالها (Timer, Counter)\n\nأعتبر هذي من أحلى المواد … خصوصا إذا فهمتها عدل … وراح تحس إنك مبدع لمن تصمم وتلعب باللاب\n\nعلى طاري اللاب 🤠 … كان له علاقة كبيرة باللكشر … في البداية يمكن عادي … بس بعدين إذا مافهمت الي باللكشر … يمكن ما تقدر تسوي شي باللاب 😡\nطبعا كان ممتع بالنسبة لي 😁 … بس عادي تقعد فيه ساعات طويلة … وتسدح الكرسي … وتفكر تفكير طوييييل 🤪 … عشان تشوف حل\nوكان عادي تطلع القطع خربانة بالأخير … حتى في لابات تكنسلت لعدم توفر القطع أو لخرابها\nبس أنا مريت اللاب السمستر الي راح … أشوف جابوا قطع جديدة … وهذا راح يريحكم كثير 👍\n\nيختلف من دكتور لآخر … البعض يطلب بروجكت نهاية اللاب … والبعض مايطلب\nيمكن البروجكت يتعبكم … لكن عن جد … راح يفيد كثيير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-204-digital-systems-design/120893/7", "user": "blood_prince", "ts": 1377066579000, "tid": 120893, "pn": 7}}', 1377066579000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1422977-cie204', 'stk-user8581', 'CIE 204', 'info', '{"desc": ":: الكورس فيه بروجكت وحاول تختار بروجكت نوعا ما سهل وقبل ما تبتدي فيه نصيحة ابحث عن القطع الي تحتاجها لاتوهق مثل بعض الشباب اضطروا يغيرون البروجكت بعدا ما ابتدوا فيه …\nهذي امثلة للبروجكت + اذا ماحصلت فكرة للبروجكت فيه ملف في لاب 409 -22 فيه مجموع كبيرة من المشاريع تقدر تسويها …\n\n- Elevator Door Control\n- Traffic Light Design\n- Customers counter in the super market\n- IR Remote Control\n- Night Rider project\n- Digital stop watch\n- basketball time out timer\n- Digital entry lock\n- Bytronic sorter unit\n- color blind illusion\n\n:: الكتاب : سيئ نوعا ما والسلايدات غالبا تكون هي المرجع للطلاب في المذاكرة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-204-digital-systems-design/120893/10", "user": "user8581", "ts": 1437934704000, "tid": 120893, "pn": 10}}', 1437934704000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1485937-cie204', 'stk-abdullah2015', 'CIE 204', 'info', '{"desc": "أنا أخذت مادة EE200 مكافئة لهذي المادة، وحسب ما أعرف فهذي المادة عندكم تغطي نفس المواضيع اللي عندنا تقريبًا لكن على أسهل\n\nباختصار اللي بتدرسه في هذي المادة أشياء جديدة ما مرت عليك لا في الأوريا ولا في الفريشمان ولا في الثانوي، وهنا تكمن صعوبة المادة\n\nتحتاج متابعة شبه أول بأول لها، لذلك المادة ذي مهما بسطها قسمكم ما أتوقع بتوصل لدرجة مادة قريد!\n\nعمومًا الوضع لا يستلزم القلق، تقدر تطلع منها بقريد بالجد والاجتهاد …\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-204-digital-systems-design/120893/15", "user": "Abdullah2015", "ts": 1515651089000, "tid": 120893, "pn": 15}}', 1515651089000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
